<script setup lang="ts">
const props=defineProps<{accountId:string;canManage:boolean}>();const {api,path,run,loading,errors}=useAuthorizationWorkspace(()=>props.accountId)
const view=ref('graph'),graph=ref<any>({nodes:[],assignments:[],associations:[]}),decision=ref<any>(null),graphSearch=ref(''),graphType=ref(''),selectedNode=ref<any>(null),deleteDialog=ref(false),impact=ref<any>(null),selectedAssociation=ref<any>(null)
const node=reactive({name:'',node_type:'user_attribute',user_identifier:'',resource_id:''}),nodeEdit=reactive({name:'',properties:'',user_identifier:null as string|null,resource_id:null as string|null}),edge=reactive({from_id:'',to_id:''}),assoc=reactive({user_attribute_id:'',object_attribute_id:'',operations:'read'}),associationOps=ref(''),check=reactive({user_id:'',object_id:'',operation:'read'})
const byType=(type:string)=>graph.value.nodes.filter((n:any)=>n.node_type===type)
const visibleGraph=computed(()=>{const ids=new Set(graph.value.nodes.filter((n:any)=>(!graphType.value||n.node_type===graphType.value)&&(!graphSearch.value||`${n.name} ${n.node_id} ${n.username||''}`.toLowerCase().includes(graphSearch.value.toLowerCase()))).map((n:any)=>n.node_id));return{nodes:graph.value.nodes.filter((n:any)=>ids.has(n.node_id)),assignments:graph.value.assignments.filter((e:any)=>ids.has(e.from_id)&&ids.has(e.to_id)),associations:graph.value.associations.filter((e:any)=>ids.has(e.user_attribute_id)&&ids.has(e.object_attribute_id))}})
const highlighted=computed(()=>decision.value?.successful_paths?.flatMap((p:any)=>[p.policy_class_id,...p.user_nodes,...p.object_nodes])||[])
async function load(){graph.value=await run('graph',()=>api(path('ngac/graph')))||graph.value;if(selectedNode.value)selectNode(graph.value.nodes.find((n:any)=>n.node_id===selectedNode.value.node_id)||null)}
async function createNode(){await run('create-node',()=>api(path('ngac/nodes'),{method:'POST',body:{name:node.name,node_type:node.node_type,user_identifier:node.node_type==='user'?node.user_identifier||null:null,resource_id:node.node_type==='object'?node.resource_id||null:null,properties:{}}}));Object.assign(node,{name:'',node_type:'user_attribute',user_identifier:'',resource_id:''});await load()}
function selectNode(value:any){selectedNode.value=value;if(value)Object.assign(nodeEdit,{name:value.name,properties:JSON.stringify(value.properties||{},null,2),user_identifier:value.username||null,resource_id:value.resource_id||null})}
async function saveNode(){if(!selectedNode.value)return;delete errors.nodeEdit;let properties={};try{properties=JSON.parse(nodeEdit.properties||'{}')}catch{return errors.nodeEdit='Properties must be valid JSON'};const body:any={name:nodeEdit.name,properties};if(selectedNode.value.node_type==='user')body.user_identifier=nodeEdit.user_identifier||null;if(selectedNode.value.node_type==='object')body.resource_id=nodeEdit.resource_id||null;await run('update-node',()=>api(path(`ngac/nodes/${selectedNode.value.node_id}`),{method:'PATCH',body}));await load()}
async function previewDelete(){if(!selectedNode.value)return;impact.value=await run('impact',()=>api(path(`ngac/nodes/${selectedNode.value.node_id}/deletion-impact`)));deleteDialog.value=!!impact.value}
async function deleteNode(){if(!selectedNode.value)return;await run('delete-node',()=>api(path(`ngac/nodes/${selectedNode.value.node_id}`),{method:'DELETE'}));selectedNode.value=null;deleteDialog.value=false;await load()}
async function assign(){await run('assign',()=>api(path('ngac/assign'),{method:'POST',body:edge}));await load()}
async function associate(){await run('associate',()=>api(path('ngac/associate'),{method:'POST',body:{...assoc,operations:assoc.operations.split(',').map(v=>v.trim())}}));await load()}
function editAssociation(value:any){selectedAssociation.value=value;associationOps.value=value.operations.join(', ')}
async function saveAssociation(){if(!selectedAssociation.value)return;await run('update-association',()=>api(path(`ngac/associations/${selectedAssociation.value.association_id}`),{method:'PATCH',body:{operations:associationOps.value.split(',').map(v=>v.trim()).filter(Boolean)}}));selectedAssociation.value=null;await load()}
async function inspect(){decision.value=null;decision.value=await run('check',()=>api(path('ngac/check'),{method:'POST',body:check}))}
watch(()=>props.accountId,()=>{graph.value={nodes:[],assignments:[],associations:[]};decision.value=null;selectedNode.value=null;selectedAssociation.value=null;deleteDialog.value=false;Object.assign(node,{name:'',node_type:'user_attribute',user_identifier:'',resource_id:''});load()},{immediate:true})
</script>
<template><div class="pa-5 pa-md-7"><v-alert v-for="(e,k) in errors" v-show="e" :key="k" type="error" variant="tonal" class="mb-3">{{e}}</v-alert><div class="d-flex"><div><h2 class="text-h5">NGAC graph</h2><p class="text-medium-emphasis">Bound and abstract nodes, typed relationships, and policy-class paths.</p></div><v-spacer/><v-btn icon="mdi-refresh" variant="text" :loading="loading.graph" @click="load"/></div><v-tabs v-model="view"><v-tab value="graph">Graph</v-tab><v-tab value="nodes">Nodes</v-tab><v-tab value="relationships">Relationships</v-tab><v-tab value="inspector">Access inspector</v-tab></v-tabs><v-window v-model="view">
<v-window-item value="graph"><v-row class="mt-3"><v-col cols="12" md="8"><v-text-field v-model="graphSearch" label="Search graph" prepend-inner-icon="mdi-magnify"/></v-col><v-col cols="12" md="4"><v-select v-model="graphType" clearable :items="['user','object','user_attribute','object_attribute','policy_class']" label="Node type"/></v-col></v-row><ClientOnly><AuthorizationNgacGraph :graph="visibleGraph" :highlight="highlighted"/></ClientOnly></v-window-item>
<v-window-item value="nodes"><v-row class="mt-3"><v-col cols="12" md="5"><v-table hover><thead><tr><th>Name</th><th>Type</th><th>Binding</th></tr></thead><tbody><tr v-for="n in graph.nodes" :key="n.node_id" :class="{'bg-primary-lighten-5':selectedNode?.node_id===n.node_id}" @click="selectNode(n)"><td>{{n.name}}<div class="text-caption xolo-mono">{{n.node_id}}</div></td><td>{{n.node_type}}</td><td>{{n.username||n.resource_id||'Abstract'}}<div v-if="n.user_id" class="text-caption xolo-mono">{{n.user_id}}</div></td></tr></tbody></v-table></v-col><v-col cols="12" md="7"><v-card v-if="selectedNode" variant="outlined" title="Node detail and editor"><v-card-text><v-text-field v-model="nodeEdit.name" label="Name" :readonly="!canManage"/><v-list density="compact"><v-list-item title="Type" :subtitle="selectedNode.node_type"/><v-list-item title="Owner" :subtitle="selectedNode.owner_id"/><v-list-item title="Created" :subtitle="new Date(selectedNode.created_at).toLocaleString()"/><v-list-item title="Updated" :subtitle="new Date(selectedNode.updated_at||selectedNode.created_at).toLocaleString()"/></v-list><TenantUserAutocomplete v-if="selectedNode.node_type==='user'" v-model="nodeEdit.user_identifier" :account-id="accountId" label="Tenant username (clear to unbind)"/><v-text-field v-if="selectedNode.node_type==='object'" v-model="nodeEdit.resource_id" clearable label="Resource ID (clear to unbind)"/><v-textarea v-model="nodeEdit.properties" label="Properties JSON" :readonly="!canManage" rows="4"/></v-card-text><v-card-actions v-if="canManage"><v-btn color="error" variant="text" @click="previewDelete">Delete</v-btn><v-spacer/><v-btn color="primary" @click="saveNode">Save node</v-btn></v-card-actions></v-card><v-card v-else-if="canManage" variant="outlined" title="Create node"><v-card-text><v-text-field v-model="node.name" label="Name"/><v-select v-model="node.node_type" :items="['user','object','user_attribute','object_attribute','policy_class']" label="Type"/><TenantUserAutocomplete v-if="node.node_type==='user'" v-model="node.user_identifier" :account-id="accountId" label="Optional tenant username"/><v-text-field v-if="node.node_type==='object'" v-model="node.resource_id" label="Optional resource ID"/></v-card-text><v-card-actions><v-spacer/><v-btn color="primary" @click="createNode">Create</v-btn></v-card-actions></v-card></v-col></v-row></v-window-item>
<v-window-item value="relationships"><v-row class="mt-3"><v-col cols="12" md="6"><v-card variant="outlined" title="Assignment"><v-card-text><v-select v-model="edge.from_id" :items="graph.nodes" item-title="name" item-value="node_id" label="Child"/><v-select v-model="edge.to_id" :items="graph.nodes" item-title="name" item-value="node_id" label="Parent"/><v-btn color="primary" :disabled="!canManage" @click="assign">Assign</v-btn></v-card-text></v-card></v-col><v-col cols="12" md="6"><v-card variant="outlined" title="Association"><v-card-text><v-select v-model="assoc.user_attribute_id" :items="byType('user_attribute')" item-title="name" item-value="node_id" label="User attribute"/><v-select v-model="assoc.object_attribute_id" :items="byType('object_attribute')" item-title="name" item-value="node_id" label="Object attribute"/><v-text-field v-model="assoc.operations" label="Lowercase operations"/><v-btn color="primary" :disabled="!canManage" @click="associate">Associate</v-btn></v-card-text></v-card></v-col></v-row><v-list><v-list-item v-for="e in graph.assignments" :key="e.assignment_id" :title="`${e.from_name} → ${e.to_name}`" :subtitle="`Assignment · ${e.assignment_id}`"/><v-list-item v-for="e in graph.associations" :key="e.association_id" :title="`${e.user_attribute_name} → ${e.object_attribute_name}`" :subtitle="`${e.operations.join(', ')} · ${e.association_id}`"><template #append><v-btn v-if="canManage" icon="mdi-pencil-outline" variant="text" @click="editAssociation(e)"/></template></v-list-item></v-list></v-window-item>
<v-window-item value="inspector"><v-card variant="outlined" class="mt-3"><v-card-text><v-select v-model="check.user_id" :items="byType('user')" item-title="name" item-value="node_id" label="User node"/><v-select v-model="check.object_id" :items="byType('object')" item-title="name" item-value="node_id" label="Object node"/><v-text-field v-model="check.operation" label="Operation"/><v-btn color="primary" @click="inspect">Inspect paths</v-btn><v-alert v-if="decision" :type="decision.allowed?'success':'error'" variant="tonal" class="mt-4">{{decision.reason}}<div>Governing classes: {{decision.governing_policy_classes.map((p:any)=>p.name).join(', ')||'none'}}</div><div v-for="item in decision.successful_paths" :key="item.policy_class_id">Allowed through {{item.policy_class_name}}: {{item.user_nodes.join(', ')}} → {{item.object_nodes.join(', ')}}</div><div v-for="item in decision.failed_classes" :key="item.policy_class_id">Failed {{item.policy_class_name}}: {{item.reason}}</div></v-alert></v-card-text></v-card></v-window-item></v-window>
<v-dialog v-model="selectedAssociation" max-width="520"><v-card title="Edit association"><v-card-text><div class="xolo-mono mb-3">{{selectedAssociation?.association_id}}</div><v-text-field v-model="associationOps" label="Operations (comma separated)"/></v-card-text><v-card-actions><v-spacer/><v-btn @click="selectedAssociation=null">Cancel</v-btn><v-btn color="primary" @click="saveAssociation">Save</v-btn></v-card-actions></v-card></v-dialog><v-dialog v-model="deleteDialog" max-width="560"><v-card title="Delete node and relationships?"><v-card-text>This deletes {{impact?.assignments?.length||0}} assignments and {{impact?.associations?.length||0}} associations connected to {{selectedNode?.name}}.</v-card-text><v-card-actions><v-spacer/><v-btn @click="deleteDialog=false">Cancel</v-btn><v-btn color="error" @click="deleteNode">Delete</v-btn></v-card-actions></v-card></v-dialog></div></template>
